    51→        .tool-card {
    52→            background: rgba(255, 255, 255, 0.05);
    53→            border-radius: 16px;
    54→            border: 1px solid rgba(255, 255, 255, 0.1);
    55→            transition: all 0.3s;
    56→            overflow: hidden;
    57→        }
    58→
