    72→        }
    73→
    74→        .tool-icon {
    75→            font-size: 32px;
    76→            margin-bottom: 12px;
    77→        }
    78→
    79→        .tool-name {
    80→            color: #00d9ff;
    81→            font-weight: 600;
    82→            font-size: 16px;
    83→            margin-bottom: 8px;
    84→        }
    85→
    86→        .tool-desc {
    87→            color: #9ca3af;
    88→            font-size: 13px;
    89→            line-height: 1.5;
    90→        }
    91→
    92→        @media (max-width: 640px) {
    93→            h1 {
    94→                font-size: 1.5rem;
    95→            }
    96→
    97→            .tools-grid {
    98→                grid-template-columns: 1fr;
    99→            }
   100→
   101→            .tool-card a {
   102→                padding: 20px;
   103→            }
   104→        }
   105→    </style>
