   180→            </a>
   181→        </li>
   182→        <li class="tool-card">
   183→            <a href="image.html">
   184→                <span class="tool-icon">🐳</span>
   185→                <span class="tool-name">Container Image Analyzer</span>
   186→                <span class="tool-desc">Inspect Docker/OCI container image layers and metadata</span>
   187→            </a>
   188→        </li>
   189→        <li class="tool-card">
   190→            <a href="kubernetes.html">
   191→                <span class="tool-icon">☸️</span>
   192→                <span class="tool-name">Kubernetes Resource Analyzer</span>
   193→                <span class="tool-desc">Analyze Pod, Deployment, StatefulSet, Job specs and best practices</span>
   194→            </a>
   195→        </li>
   196→        <li class="tool-card">
   197→            <a href="calendar.html">
   198→                <span class="tool-icon">📆</span>
   199→                <span class="tool-name">Calendar</span>
   200→                <span class="tool-desc">A printable calendar with the full year on a single page</span>
   201→            </a>
   202→        </li>
